//! Renderables compared line by line with real `rich` output (see `golden.rs`, generated by
//! `scripts/rich_golden.py`; every scenario here mirrors one there).

use super::box_styles as boxes;
use super::*;
use crate::text::{Justify, TextOverflow};

include!("golden.rs");

const WORDS: &[&str] = &[
    "alpha", "bravo", "charlie", "delta", "echo", "foxtrot", "golf", "hotel", "india", "juliett",
    "kilo", "lima", "mike", "november", "oscar", "papa", "quebec", "romeo", "sierra", "tango",
];

fn check(name: &str, renderable: &dyn Renderable, width: i32, expected: &[&str]) {
    let lines: Vec<String> = render_lines(renderable, &RenderOptions::new(width))
        .iter()
        .map(Strip::plain_text)
        .collect();
    let expected: Vec<String> = expected.iter().map(|s| s.to_string()).collect();
    assert_eq!(
        lines,
        expected,
        "{name} at width {width}:\n--- rustual\n{}\n--- rich\n{}",
        lines.join("\n"),
        expected.join("\n")
    );
}

fn star_wars(f: impl FnOnce(Table) -> Table) -> Table {
    let mut t = f(Table::new()
        .title("Star Wars Movies")
        .caption("Rich example table"));
    t.add_column_with("Released", |c| c.no_wrap(true));
    t.add_column("Title");
    t.add_column_with("Box Office", |c| c.justify(Justify::Right));
    t.add_row([
        "Dec 20, 2019",
        "Star Wars: The Rise of Skywalker",
        "$952,110,690",
    ]);
    t.add_row(["May 25, 2018", "Solo: A Star Wars Story", "$393,151,347"]);
    t.add_row_styled(
        [
            "Dec 15, 2017",
            "Star Wars Ep. V111: The Last Jedi",
            "$1,332,539,889",
        ],
        Style::default(),
        true,
    );
    t.add_row([
        "Dec 16, 2016",
        "Rogue One: A Star Wars Story",
        "$1,332,439,889",
    ]);
    t
}

fn grid() -> Table {
    let mut t = Table::grid().padding(Spacing::symmetric(0, 2));
    t.add_column("");
    t.add_column_with("", |c| c.justify(Justify::Right));
    t.add_row(["Name:", "rustual"]);
    t.add_row(["Version:", "0.4"]);
    t
}

#[test]
fn table_star_wars() {
    let t = star_wars(|t| t);
    check("star_wars", &t, 80, TABLE_STAR_WARS_80);
    check("star_wars", &t, 60, TABLE_STAR_WARS_60);
    check("star_wars", &t, 40, TABLE_STAR_WARS_40);
    check("star_wars", &t, 30, TABLE_STAR_WARS_30);
    check(
        "expand",
        &star_wars(|t| t.expand(true)),
        90,
        TABLE_STAR_WARS_EXPAND_90,
    );
    check(
        "width",
        &star_wars(|t| t.width(50)),
        80,
        TABLE_STAR_WARS_WIDTH_80,
    );
}

#[test]
fn table_options() {
    let mut t = Table::new().expand(true);
    t.add_column_with("A", |c| c.ratio(1));
    t.add_column_with("B", |c| c.ratio(2));
    t.add_column("Fixed");
    t.add_row(["one", "two", "three"]);
    check("ratio", &t, 50, TABLE_RATIO_50);

    let mut t = Table::new().show_lines(true);
    t.add_column("Key");
    t.add_column_with("Value", |c| c.vertical(VerticalAlign::Middle));
    t.add_row(["a", "1"]);
    t.add_row(["multi\nline", "2"]);
    t.add_row(["c", "3"]);
    check("lines", &t, 40, TABLE_LINES_40);

    let mut t = Table::new().leading(1).box_style(Some(boxes::SQUARE));
    t.add_column("x");
    t.add_column("y");
    t.add_row(["1", "2"]);
    t.add_row(["3", "4"]);
    check("leading", &t, 40, TABLE_LEADING_40);

    let mut t = Table::new()
        .show_header(false)
        .box_style(Some(boxes::ROUNDED))
        .show_edge(false);
    t.add_column("");
    t.add_column("");
    t.add_row(["left", "right"]);
    t.add_row(["more text here", "x"]);
    check("plain", &t, 40, TABLE_PLAIN_40);

    let mut t = Table::new()
        .show_footer(true)
        .box_style(Some(boxes::MINIMAL_HEAVY_HEAD));
    t.add_column_with("Item", |c| c.footer("Total"));
    t.add_column_with("Price", |c| c.footer("$3").justify(Justify::Right));
    t.add_row(["apple", "$1"]);
    t.add_row(["pear", "$2"]);
    check("footer", &t, 40, TABLE_FOOTER_40);

    check("grid", &grid(), 40, TABLE_GRID_40);

    let mut t = Table::new().min_width(40);
    t.add_column("a");
    t.add_column("b");
    t.add_row(["1", "2"]);
    check("min_width", &t, 80, TABLE_MIN_WIDTH_80);

    let mut t = Table::new().box_style(Some(boxes::ASCII));
    t.add_column("Outer");
    t.add_column("Inner");
    t.add_row([
        "cell".into_renderable(),
        Panel::fit("boxed").into_renderable(),
    ]);
    check("nested", &t, 40, TABLE_NESTED_40);

    let mut t = Table::new();
    t.add_column_with("Name", |c| c.overflow(TextOverflow::Fold));
    t.add_column("Description");
    t.add_column_with("Code", |c| c.no_wrap(true));
    t.add_row([
        "supercalifragilistic",
        "a long description that will need to wrap",
        "abc-123",
    ]);
    check("wide_cells", &t, 40, TABLE_WIDE_CELLS_40);
    check("wide_cells", &t, 24, TABLE_WIDE_CELLS_24);
}

#[test]
fn panels() {
    check("basic", &Panel::new("Hello, World!"), 30, PANEL_BASIC_30);
    check(
        "fit_titles",
        &Panel::fit("Hello")
            .title("Title")
            .subtitle("sub")
            .subtitle_align(Justify::Right),
        40,
        PANEL_FIT_TITLES_40,
    );
    let p = Panel::fit("x").title("a much longer title");
    check("long_title", &p, 40, PANEL_LONG_TITLE_40);
    check("long_title", &p, 12, PANEL_LONG_TITLE_12);
    check(
        "wrap",
        &Panel::new("The quick brown fox jumps over the lazy dog")
            .box_style(boxes::DOUBLE)
            .padding(Spacing::symmetric(1, 2)),
        24,
        PANEL_WRAP_24,
    );
    check(
        "height",
        &Panel::new("x")
            .height(5)
            .title("t")
            .title_align(Justify::Left),
        12,
        PANEL_HEIGHT_12,
    );
}

#[test]
fn columns() {
    let c = Columns::new(WORDS.iter().copied());
    check("words", &c, 40, COLUMNS_WORDS_40);
    check("words", &c, 25, COLUMNS_WORDS_25);
    check(
        "column_first",
        &Columns::new(WORDS.iter().copied()).column_first(true),
        40,
        COLUMNS_COLUMN_FIRST_40,
    );
    check(
        "equal_expand",
        &Columns::new(WORDS[..7].iter().copied())
            .equal(true)
            .expand(true),
        50,
        COLUMNS_EQUAL_EXPAND_50,
    );
    check(
        "align_right",
        &Columns::new(WORDS[..6].iter().copied())
            .equal(true)
            .align(Justify::Right),
        30,
        COLUMNS_ALIGN_RIGHT_30,
    );
    check(
        "width",
        &Columns::new(WORDS[..5].iter().copied()).width(8),
        30,
        COLUMNS_WIDTH_30,
    );
}

#[test]
fn padding_and_group() {
    check(
        "padding",
        &Padding::new("Hi", Spacing::symmetric(1, 2)),
        10,
        PADDING_10,
    );
    check(
        "group",
        &Group::new([Panel::fit("a").into_renderable(), "text".into_renderable()]),
        20,
        GROUP_20,
    );
}

#[test]
fn measurements() {
    let m = |r: &dyn Renderable| {
        let m = measure(r, &RenderOptions::new(80));
        (m.minimum, m.maximum)
    };
    assert_eq!(m(&star_wars(|t| t)), MEASURE_STAR_WARS);
    assert_eq!(m(&Panel::fit("Hello").title("Title")), MEASURE_PANEL_FIT);
    assert_eq!(m(&Text::plain("hello wonderful\nworld")), MEASURE_TEXT);
    assert_eq!(m(&grid()), MEASURE_GRID);
}

#[test]
fn styles_reach_the_cells() {
    let mut t = Table::new().border_style(Style::parse("red").unwrap());
    t.add_column_with("H", |c| c.style(Style::parse("green").unwrap()));
    t.add_row(["[b]x[/]"]);
    let lines = render_lines(&t, &RenderOptions::new(10));
    let red = Style::parse("red").unwrap().fg;
    assert_eq!(lines[0].spans[0].style.fg, red);
    // Header: bold by default.
    let header = &lines[1];
    let h = header.spans.iter().find(|s| s.text.contains('H')).unwrap();
    assert_eq!(h.style.bold, Some(true));
    // Body cell: column style beneath the markup.
    let body = &lines[3];
    let x = body.spans.iter().find(|s| s.text.contains('x')).unwrap();
    assert_eq!(x.style.bold, Some(true));
    assert_eq!(x.style.fg, Style::parse("green").unwrap().fg);
}
